package main

import (
	"log"
	"net/http"
	"os"
)

func main() {
	db := os.Getenv("DATABASE_URL")
	if db == "" {
		log.Fatal("DATABASE_URL is required")
	}
	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}
	if dsn := os.Getenv("SENTRY_DSN"); dsn != "" {
		initSentry(dsn)
	}
	if os.Getenv("LEDGER_BATCH_EXPORT") == "1" {
		go runBatchExport(db)
	}
	log.Fatal(http.ListenAndServe(":"+port, routes(db)))
}

